const res = $input.all(); const req = $('Build').all();
if (req.length && req[0].json.none) return [req[0].json];
let ok = 0; const bad = [];
for (let i = 0; i < res.length; i++) {
  const r = res[i].json; const q = req[i].json;
  const got = r.body && r.body.translation ? r.body.translation.translation : undefined;
  if (r.statusCode === 200 && got === q.want) ok++;
  else bad.push({ k: q.k, iso: q.iso, status: r.statusCode, got: String(got).slice(0, 200), err: JSON.stringify((r.body && r.body.error) || r.error || '').slice(0, 200) });
}
return [{ json: { written_ok: ok, attempted: res.length, bad, keys: req.map(x => x.json.k) } }];
